$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$python = Join-Path $root ".venv\Scripts\python.exe"
$bridgePath = Join-Path $pkg "ahos\opportunity_missions.py"
$testPath = Join-Path $pkg "tests\test_opportunity_missions.py"
$patcher = Join-Path $env:TEMP "ahos-040-patch.py"
$proofDb = Join-Path $pkg "runtime\AHOS-040-proof.db"

Write-Host "=== AHOS-040 OPPORTUNITY TO MISSION QUEUE ==="
Write-Host "LOCAL / READ-ONLY OUTSIDE WORLD"
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host ""

if (-not (Test-Path $python)) { throw "Python venv not found." }
if (-not (Test-Path $pkg)) { throw "AHOS package not found." }

[IO.File]::WriteAllBytes(
    $bridgePath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $testPath,
    [Convert]::FromBase64String("")
)

$patchText = [Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String("")
)
$patchText = $patchText.Replace("__PKG__", $pkg.Replace("\","\\"))
[IO.File]::WriteAllText(
    $patcher,
    $patchText,
    (New-Object System.Text.UTF8Encoding($false))
)

& $python $patcher
if ($LASTEXITCODE -ne 0) { throw "AHOS-040 patch failed." }

$old = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg

    Write-Host "Running opportunity-to-mission tests..."
    & $python -m pytest tests\test_opportunity_missions.py -q
    if ($LASTEXITCODE -ne 0) {
        throw "AHOS-040 focused tests failed."
    }

    Write-Host "Running full AHOS test suite..."
    & $python -m pytest -q
    if ($LASTEXITCODE -ne 0) {
        throw "Full AHOS tests failed."
    }

    Remove-Item $proofDb -Force -ErrorAction SilentlyContinue
    Write-Host "Running zero-cost local proof..."
    $proof = @'
from pathlib import Path
from ahos.autonomous_company import PersistentMissionQueue
from ahos.candidate_triage import CandidateDisposition, CandidateTriage
from ahos.opportunity_intake import OpportunityCandidate
from ahos.opportunity_missions import QualifiedOpportunityMissionBridge

db = Path(r"__PROOF_DB__")
queue = PersistentMissionQueue(db)
candidate = OpportunityCandidate(
    candidate_id="proof-animation-lead",
    source_id="local-proof",
    source_url="https://example.test/feed",
    item_url="https://example.test/project",
    title="Freelance Animation Automation Project",
    description="Build an automation workflow for animation production.",
    category="creative",
    discovered_at="2026-09-19T00:00:00+00:00",
    raw_metadata={},
)
triage = CandidateTriage(
    candidate_id=candidate.candidate_id,
    title=candidate.title,
    source_id=candidate.source_id,
    item_url=candidate.item_url,
    category=candidate.category,
    score=92,
    disposition=CandidateDisposition.BUSINESS_LEAD,
    reasons=("strong project signal", "delivery-oriented language"),
    matched_positive_terms=("automation", "workflow"),
    matched_negative_terms=(),
    explicit_project_signal=True,
    project_signal_source="title:freelance",
    employment_signal=False,
)
decision = QualifiedOpportunityMissionBridge(queue).convert(candidate, triage=triage)
mission = queue.get(decision.mission_id)
print("QUEUED:", decision.queued)
print("MISSION:", mission.mission_id)
print("STATUS:", mission.status.value)
print("DEPARTMENT:", mission.primary_department)
print("READ_ONLY_GUARD:", "Do not contact" in mission.objective)
'@
    $proof = $proof.Replace("__PROOF_DB__", $proofDb.Replace("\","\\"))
    $proof | & $python -
    if ($LASTEXITCODE -ne 0) {
        throw "AHOS-040 local proof failed."
    }
}
finally {
    Pop-Location
    $env:PYTHONPATH = $old
    Remove-Item $patcher -Force -ErrorAction SilentlyContinue
    Remove-Item $proofDb -Force -ErrorAction SilentlyContinue
}

git -C $ws add `
    ahos_core/ahos/opportunity_missions.py `
    ahos_core/tests/test_opportunity_missions.py `
    ahos_core/AHOS_BACKLOG.json

$staged = git -C $ws diff --cached --name-only
if ($staged) {
    git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" `
        commit -m "feat(ahos): queue qualified opportunity missions"
    if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

    git -C $ws push origin HEAD
    if ($LASTEXITCODE -ne 0) { throw "git push failed." }
} else {
    Write-Host "Git: no staged changes; AHOS-040 already present."
}

Write-Host ""
Write-Host "=== AHOS-040 COMPLETE ==="
Write-Host "Qualified BUSINESS_LEAD -> mission: PASS"
Write-Host "Non-qualified candidates filtered: PASS"
Write-Host "Persistent queue integration: PASS"
Write-Host "Stable mission IDs / duplicate protection: PASS"
Write-Host "Deterministic department selection: PASS"
Write-Host "External apply/bid/message/payment/publish/deploy actions: 0"
Write-Host "Full AHOS tests: PASS"
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host ""
Write-Host "CORE ROADMAP REMAINING: AHOS-041 and AHOS-042."
Write-Host "NEXT: AHOS-041 Holding Control Center dashboard."
